// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(bytes32 assertionId) public {
        vm.assume(assertionId != bytes32(0));

        // Call getAssertionPolicy to check the arbitrateViaEscalationManager field
        C.AssertionPolicy memory policy = c.getAssertionPolicy(assertionId);

        // The general rule: arbitrateViaEscalationManager must always be false
        assertTrue(!policy.arbitrateViaEscalationManager, "arbitrateViaEscalationManager should be false");
    }
}

